-- =========================================================
-- FRELUX Comprehensive Engine Inventory & 20-Market Matrix Migration
-- Migration: 20261014150000_comprehensive_engine_inventory.sql
--
-- Purely additive. Records all 54 discovered engines, sub-engines,
-- calculation pathways, and their honest 20-market support statuses.
-- Enables Admin and system visibility into full calculation surface.
-- =========================================================

CREATE TABLE IF NOT EXISTS comprehensive_engine_inventory (
  id text PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  classification text NOT NULL,
  source_files text[] NOT NULL,
  consumers text[] NOT NULL,
  dependencies text[] NOT NULL,
  calculation_purpose text NOT NULL,
  key_formulas text NOT NULL,
  market_assumptions text NOT NULL,
  internationalization_status text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS engine_market_support_matrix (
  engine_id text NOT NULL REFERENCES comprehensive_engine_inventory(id) ON DELETE CASCADE,
  market_code text NOT NULL,
  status text NOT NULL,
  notes text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (engine_id, market_code)
);

ALTER TABLE comprehensive_engine_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE engine_market_support_matrix ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'comprehensive_engine_inventory' AND policyname = 'Public read comprehensive_engine_inventory'
  ) THEN
    CREATE POLICY "Public read comprehensive_engine_inventory"
      ON comprehensive_engine_inventory FOR SELECT USING (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'engine_market_support_matrix' AND policyname = 'Public read engine_market_support_matrix'
  ) THEN
    CREATE POLICY "Public read engine_market_support_matrix"
      ON engine_market_support_matrix FOR SELECT USING (true);
  END IF;
END $$;

-- Seed Comprehensive Engine Inventory
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  classification = EXCLUDED.classification,
  source_files = EXCLUDED.source_files,
  consumers = EXCLUDED.consumers,
  dependencies = EXCLUDED.dependencies,
  calculation_purpose = EXCLUDED.calculation_purpose,
  key_formulas = EXCLUDED.key_formulas,
  market_assumptions = EXCLUDED.market_assumptions,
  internationalization_status = EXCLUDED.internationalization_status,
  updated_at = now();

-- Seed Engine Market Support Matrix (1080 rows)
ON CONFLICT (engine_id, market_code) DO UPDATE SET
  status = EXCLUDED.status,
  notes = EXCLUDED.notes,
  updated_at = now();
