INSERT INTO comprehensive_engine_inventory (id, name, category, classification, source_files, consumers, dependencies, calculation_purpose, key_formulas, market_assumptions, internationalization_status) VALUES
('painting', 'Painting Calculation Engine', 'finishing', 'independent_engine', ARRAY['src/lib/estimation/paint-engine.ts', 'src/lib/estimation/painting-engine.ts', 'src/lib/calc.ts'], ARRAY['src/pages/calculator/PaintingCalculator.tsx', 'src/pages/calculator/ComprehensivePaintCalculator.tsx', 'src/lib/ai-foundation/engines-phase2.ts'], ARRAY['src/lib/estimation/pack-sizing.ts', 'src/lib/estimation/market-materials.ts', 'src/lib/wallfinishing/assemblies.ts'], 'Calculates wall/ceiling surface area minus openings, paint volume per coat, container packaging (e.g. 4L / 10L / 20L / 1 US gal / 5 US gal), and material costs.', 'NetArea = GrossWallArea - OpeningsArea + DeductionAllowances; Litres = NetArea * Coats / SpreadingRate; Containers = ceil(Litres / PackSize)', 'Pack sizes: 20L/4L in NG/GH/KE/IN; 1 gal / 5 gal in US; 2.5L / 5L / 10L in GB/EU. Spreading rate depends on substrate absorption.', 'verified_15_markets'),
('screeding', 'Screeding & Skim Coat Engine', 'finishing', 'independent_engine', ARRAY['src/lib/calc.ts', 'src/lib/wallfinishing/assemblies.ts', 'src/lib/wallfinishing/quantity-engine.ts'], ARRAY['src/pages/calculator/ScreedingCalculator.tsx', 'src/lib/ai-foundation/engines-phase2.ts'], ARRAY['src/lib/wallfinishing/materials.ts', 'src/lib/estimation/pack-sizing.ts'], 'Calculates putty/skim coat quantities (20kg/40kg bags), acrylic primer, and sandpaper sheets for interior wall preparation.', 'Bags = ceil(NetArea / CoveragePerBag); PrimerLitres = NetArea / PrimerSpreadRate; Sandpaper = ceil(NetArea * 0.05)', '40kg bags in IN (Birla White); 20kg bags in NG/GH/KE/ZA; ready-mix joint compound buckets in US/CA (USG Sheetrock 4.5 gal / 12L).', 'verified_15_markets'),
('pop_ceiling', 'POP & Suspended Ceiling Engine', 'finishing', 'independent_engine', ARRAY['src/lib/pop-tile-calc.ts', 'src/lib/calc.ts'], ARRAY['src/pages/calculator/PopCeilingCalculator.tsx', 'src/lib/ai-foundation/engines-phase2.ts'], ARRAY['src/lib/measurement/geometry-utils.ts'], 'Computes plaster of Paris bags, mesh, fibre/sponge, binding wire, and cornices for ceilings.', 'CeilingArea = Length * Width; PopBags = ceil(CeilingArea / 3.5); Fibre = ceil(CeilingArea / 25); CorniceMetres = Perimeter * 1.1', 'Wet cast POP in West Africa (NG/GH); suspended gypsum plasterboard (drywall) with metal furring channels in US/GB/EU/AU.', 'verified_15_markets'),
('tile', 'Tile & Grout Calculation Engine', 'finishing', 'independent_engine', ARRAY['src/lib/pop-tile-calc.ts', 'src/lib/estimation/flooring-engine.ts'], ARRAY['src/pages/calculator/TileCalculator.tsx', 'src/lib/ai-foundation/engines-phase2.ts'], ARRAY['src/lib/estimation/pack-sizing.ts'], 'Calculates tile carton counts based on tile dimensions, grout bags, cement adhesive, and tile spacers with cutting waste.', 'NetArea = RoomArea * (1 + WasteRate); TileCount = ceil(NetArea / TileArea); Cartons = ceil(TileCount / TilesPerCarton)', 'Tile cartons specified in m² per carton or sq ft per carton. Cement-based adhesive (20kg/25kg bags) and 2-5kg grout bags.', 'verified_15_markets'),
('wall_finishing', 'Comprehensive Wall Finishing Engine', 'finishing', 'independent_engine', ARRAY['src/lib/wallfinishing/quantity-engine.ts', 'src/lib/wallfinishing/cost-engine.ts', 'src/lib/wallfinishing/assemblies.ts'], ARRAY['src/pages/calculator/WallFinishingEstimator.tsx', 'src/pages/calculator/WallFinishingProject.tsx'], ARRAY['src/lib/wallfinishing/materials.ts', 'src/lib/wallfinishing/resolver.ts'], 'Multi-layer wall finishing pipeline: evaluates substrate, primer, skim coats, paint coats, wallpapers, and edge trims across assemblies.', 'AssemblyLayers.forEach(layer => layer.calculate(area, substrateFactors, wasteRates))', 'Full 20-market verified assembly sequences from ABNT (BR), DTU (FR), DIN (DE), BS (GB), ASTM (US), SANS (ZA), etc.', 'verified_15_markets'),
('tyrolene', 'Tyrolene Textured Finish Engine', 'finishing', 'independent_engine', ARRAY['src/lib/estimation/tyrolene-engine.ts'], ARRAY['src/pages/calculator/TyroleneCalculator.tsx', 'src/lib/ai-foundation/engines-phase2.ts'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates white/grey cement, fine sand, tyrolene machine application rates, and exterior sealer for textured splattered render.', 'CementBags = Area * 0.12; SandTonnes = Area * 0.015; SealerLitres = Area / 8', 'West African and UK heritage exterior roughcast/machine splattered finish. Bound to regional wet render methods in NG/GH.', 'market_method_bound'),
('grafitex', 'Grafitex Textured Plaster Engine', 'finishing', 'independent_engine', ARRAY['src/lib/finish-calc.ts'], ARRAY['src/pages/calculator/GrafitexCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Computes acrylic trowel-applied textured plaster (grafitex) drums/pails (20kg/30kg) and matching primer base.', 'Drums = ceil(Area / (20 / ConsumptionRateKgPerM2)); PrimerLitres = ceil(Area / 7.5)', 'Common in West African exterior facades. Bound to regional supply in Nigeria/Ghana.', 'market_method_bound'),
('mineral_stone', 'Mineral Stone Wall Finish Engine', 'finishing', 'independent_engine', ARRAY['src/lib/estimation/mineral-stone-engine.ts'], ARRAY['src/pages/calculator/MineralStoneCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates crushed natural stone aggregates, epoxy/acrylic binder resin, clear topcoat sealer, and application tools.', 'StoneBags = ceil(Area * Thickness * BulkDensity / BagWeight); ResinLitres = Area * ResinCoverage', 'Architectural specialty aggregate finish. Verified in NG; portable to other markets with local supplier aggregate listings.', 'requires_verification'),
('stucco', 'Stucco Render Engine', 'finishing', 'independent_engine', ARRAY['src/lib/estimation/mineral-stone-engine.ts'], ARRAY['src/pages/calculator/StuccoCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Computes multi-coat exterior portland cement stucco (scratch, brown, and acrylic finish coats) with lath wire.', 'CementSandScratch = Area * 0.01 * Density; FinishCoat = Area * FinishCoverage', '3-coat system over wire lath (US/MX) vs 2-coat direct-applied masonry stucco (NG/EU).', 'requires_verification'),
('flooring', 'Flooring & Screed Takeoff Engine', 'finishing', 'independent_engine', ARRAY['src/lib/estimation/flooring-engine.ts'], ARRAY['src/pages/calculator/FlooringCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates floor finishes (hardwood, laminate, vinyl LVP, epoxy, floor screed) with underlayment and perimeter expansion trims.', 'ScreedVolume = FloorArea * Thickness; CementBags = ScreedVolume * CementRatio; UnderlaymentRolls = ceil(FloorArea * 1.05 / RollArea)', 'Metric thickness (mm) vs US imperial inches; packaging rolls and plank box sizes.', 'requires_verification'),
('waterproofing', 'Waterproofing System Engine', 'finishing', 'independent_engine', ARRAY['src/lib/estimation/waterproofing-engine.ts'], ARRAY['src/pages/calculator/WaterproofingCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates liquid elastomeric membranes, bituminous torch-on rolls, cementitious crystallization slurry, and joint geotextile tape.', 'MembraneRolls = ceil(Area * 1.15 / RollArea); PrimerLitres = Area / PrimerCoverage; ReinforcingTape = Perimeter * 1.1', 'Torch-on SBS rolls (1m x 10m) in EU/ME; liquid polyurethane/acrylic in US/AU/Africa.', 'requires_verification'),
('doors_windows', 'Doors & Windows Takeoff Engine', 'structural', 'independent_engine', ARRAY['src/lib/estimation/doors-windows-engine.ts'], ARRAY['src/pages/calculator/DoorsWindowsCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Computes rough opening deductions, door frames, architraves, ironmongery/hardware sets, glazing areas, and sealant lengths.', 'TotalOpeningArea = sum(Width * Height); ArchitraveLength = sum(2 * Height + Width); SealantTubes = ceil(sum(Perimeter) / 10)', 'Modular standard door dimensions (e.g. 2ft 8in x 6ft 8in US; 826x2040mm UK; 900x2100mm NG/EU).', 'requires_verification'),
('block', 'Block & Masonry Calculation Engine', 'structural', 'independent_engine', ARRAY['src/lib/calc.ts', 'src/lib/estimation/build-to-roof-engine.ts'], ARRAY['src/pages/calculator/BlockCalculator.tsx', 'src/pages/calculator/BuildToRoofCalculator.tsx'], ARRAY['src/lib/estimation/construction-typologies.ts'], 'Calculates wall masonry units (sandcrete blocks, clay bricks, CMUs, AAC blocks, machine stones) and bedding mortar.', 'UnitCount = ceil(WallNetArea / UnitFaceArea * (1 + WasteRate)); MortarVolume = WallNetArea * BedJointArea', 'Sandcrete in NG/GH; Red Brick in ID/IN; CMU in US/FR; Facing Brick Cavity in GB/ZA; Poroton in DE/IT; Stone in KE.', 'partially_verified'),
('roofing', 'Roofing Material & Sheets Engine', 'structural', 'independent_engine', ARRAY['src/lib/calc.ts', 'src/lib/roof/roof-material-engine.ts'], ARRAY['src/pages/calculator/RoofingCalculator.tsx'], ARRAY['src/lib/roof/geometry-engine.ts'], 'Calculates roof coverings: corrugated aluminium/galvanised sheets, standing seam, stone-coated tiles, asphalt shingles, and ridge caps.', 'EffectiveSheetCoverage = (SheetWidth - SideOverlap) * (SheetLength - EndLap); SheetsCount = ceil(TrueSlopeArea / EffectiveSheetCoverage)', 'Long-span aluminium in NG/GH; Asphalt shingles in US/CA; Interlocking concrete/clay tiles in GB/EU/AU/ZA.', 'partially_verified'),
('build_to_roof', 'Build to Roof Whole-Structure Engine', 'structural', 'independent_engine', ARRAY['src/lib/estimation/build-to-roof-engine.ts'], ARRAY['src/pages/calculator/BuildToRoofCalculator.tsx', 'src/lib/ai-foundation/engines-registry.ts'], ARRAY['src/lib/estimation/construction-typologies.ts', 'src/lib/roof/geometry-engine.ts'], 'Full building takeoff from foundation excavation through German floor, blockwork, lintels, columns, and timber roof carcass.', 'Multi-stage pipeline: TrenchVolume -> FoundationConcrete -> Blockwork -> GermanFloorSlab -> Columns -> LintelBeams -> RoofTimber -> Sheets', 'West African load-bearing sandcrete construction. Correctly gated as not_implemented for North American timber frame markets.', 'market_method_bound'),
('foundation', 'Foundation Design & Takeoff Engine', 'structural', 'independent_engine', ARRAY['src/lib/estimation/foundation-engine.ts', 'src/lib/engineering/foundation-design.ts'], ARRAY['src/pages/calculator/FoundationCalculator.tsx'], ARRAY['src/lib/estimation/construction-typologies.ts'], 'Calculates trench excavation, blinding concrete, foundation strip/pad footings, DPC membrane, hardcore filling, and slab concrete.', 'ExcavationVolume = Perimeter * TrenchWidth * TrenchDepth; FootingConcrete = Perimeter * Width * Thickness; HardcoreVolume = SlabArea * HardcoreDepth', 'Strip footings in NG/GH/GB; Frost-line footings (up to 1.8m) in CA/DE/KR; Waffle pod slabs in AU; Rafts on expansive clay in ZA/IN.', 'partially_verified'),
('structural', 'Structural Concrete Elements Engine', 'structural', 'independent_engine', ARRAY['src/lib/engineering/structural-design.ts'], ARRAY['src/pages/calculator/StructuralCalculator.tsx'], ARRAY['src/lib/estimation/construction-typologies.ts'], 'Preliminary element sizing and material takeoff for reinforced concrete beams, columns, and slabs.', 'BeamConcrete = Length * Width * Depth; ColumnConcrete = Height * Width * Depth * ColumnCount; FormworkArea = ContactPerimeter * Length', 'Characteristic concrete cube strength (e.g. C20/25, C25/30) and cylinder strength (psi in US: 3000-4000 psi).', 'partially_verified'),
('reinforcement', 'Reinforcement Steel (Rebar) Engine', 'structural', 'independent_engine', ARRAY['src/lib/estimation/reinforcement-engine.ts'], ARRAY['src/pages/calculator/ReinforcementCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates rebar bar counts (12m / 40ft lengths), tonnage, cutting/bending waste, laps, links/stirrups, and binding wire.', 'UnitWeightKgPerM = (Diameter_mm ^ 2) / 162; BarCount = ceil(TotalLength / 12 * 1.1); Tonnage = BarCount * 12 * UnitWeight / 1000', 'High-yield deformed bars 500 MPa (Y12, Y16, Y20 in UK/Africa/EU; #4, #5, #6 in US 60 ksi; Fe500 in India).', 'partially_verified'),
('electrical', 'Electrical Installation Engine', 'mep', 'independent_engine', ARRAY['src/lib/estimation/electrical-engine.ts', 'src/lib/estimation/electrical-profiles.ts'], ARRAY['src/pages/calculator/ElectricalCalculator.tsx'], ARRAY['src/lib/estimation/electrical-profiles.ts', 'src/lib/estimation/market-materials.ts'], 'Deterministic electrical material takeoff: cable lengths, conduits, flush/surface back boxes, circuit breakers, RCDs, consumer unit.', 'LightingCable = sum(Runs) * 1.1; SocketCable = sum(Runs) * 1.1; ConduitLength = sum(Runs); BreakerCount = ceil(LightingPoints / MaxPerCircuit)', '20 verified market profiles: NEC/Romex (US), BS 7671 (GB), SANS (ZA), NF C 15-100 (FR), DIN (DE), JIS (JP), etc.', 'verified_full'),
('plumbing', 'Plumbing Sanitary & Supply Engine', 'mep', 'independent_engine', ARRAY['src/lib/estimation/plumbing-engine.ts', 'src/lib/estimation/plumbing-profiles.ts'], ARRAY['src/pages/calculator/PlumbingCalculator.tsx'], ARRAY['src/lib/estimation/plumbing-profiles.ts', 'src/lib/estimation/market-materials.ts'], 'Deterministic plumbing material takeoff: cold water, hot water, waste, and soil pipes, fittings, valves, and septic connections.', 'PipeLengths = sum(UserRuns) * (1 + WasteRate); FittingAllowance = FixtureCount * AllowancePerFixture', '20 verified market profiles: IPC/UPC (US), AS/NZS 3500 (AU), DIN 1988 (DE), DTU 60.1 (FR), SNI (ID), JIS (JP), etc.', 'verified_full'),
('generator', 'Backup Generator Sizing Engine', 'mep', 'independent_engine', ARRAY['src/lib/estimation/generator-engine.ts'], ARRAY['src/pages/calculator/GeneratorCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Computes continuous running load (kW/kVA), motor inductive starting surges, power factor, fuel consumption rate, and ATS rating.', 'RunningKva = sum(Appliances.Watts) / (1000 * PF); PeakSurgeKva = RunningKva + max(MotorSurges); GeneratorRatingKva = PeakSurgeKva * 1.25', 'Diesel vs petrol fuel; 50Hz (230V/400V) in Africa/EU/Asia vs 60Hz (120V/240V) in US/CA/MX/KR/BR.', 'partially_verified'),
('solar_pv', 'Solar PV & Battery System Engine', 'mep', 'independent_engine', ARRAY['src/lib/calc.ts'], ARRAY['src/pages/calculator/SolarPvCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates solar panel wattage, string inverter / micro-inverter capacity, lithium/gel battery storage, charge controllers, and mounting rails.', 'DailyWattHours = sum(Load * Hours); RequiredArrayWp = DailyWattHours / (PeakSunHours * PR); BatteryKwh = DailyWattHours * AutonomyDays / DoD', 'Peak sun hours vary geographically (3.0 kWh/m²/day in UK/DE to 5.5-6.5 kWh/m²/day in SA/AE/NG/AU).', 'requires_verification'),
('heat_comfort', 'Thermal Comfort & Heat Gain Engine', 'mep', 'independent_engine', ARRAY['src/lib/calc.ts'], ARRAY['src/pages/calculator/HeatComfortCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates building envelope heat transmission, solar heat gain coefficient (SHGC), U-values, and heating/cooling BTU requirement.', 'HeatLoss = sum(Area * UValue * DeltaT); SolarGain = GlazingArea * SHGC * SolarIrradiance', 'Climatic heating degree days (HDD) and cooling degree days (CDD) across temperate and tropical zones.', 'requires_verification'),
('cost_estimator', 'Regional Cost & Pricing Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/calc.ts', 'src/lib/estimation/regional-cost-engine.ts'], ARRAY['src/pages/calculator/CostEstimator.tsx'], ARRAY['src/lib/estimation/regional-cost-engine.ts', 'src/lib/estimation/market-materials.ts'], 'Consolidates multi-trade material and labour costs with regional cost indices and inflation multipliers.', 'TotalCost = (MaterialsSubtotal + LabourSubtotal + PlantSubtotal) * RegionalFactor * (1 + ContingencyRate)', 'Multi-currency support with explicit ISO currency codes, market pricing sources, and transparent regional multiplier fallbacks.', 'verified_full'),
('labour_estimator', 'Labour & Crew Productivity Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/labour-crew-engine.ts'], ARRAY['src/pages/calculator/LabourEstimator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Calculates trade labour requirements (man-days, crew compositions, daily output rates, wage rates) per construction task.', 'ManDays = WorkQuantity / DailyOutputPerCraftsman; TotalLabourCost = ManDays * DailyWageRate', 'Local daily/hourly wages by trade. Union vs market rates; crew productivity adjustments by region.', 'partially_verified'),
('margin_calculator', 'Contractor Margin & Markup Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/margin-engine.ts'], ARRAY['src/pages/calculator/MarginCalculator.tsx'], ARRAY[]::text[], 'Calculates contractor gross margin, markup percentage, company overhead allocation, and net pre-tax profit.', 'SellingPrice = DirectCost / (1 - MarginRate); Markup = (SellingPrice - DirectCost) / DirectCost; NetProfit = SellingPrice - DirectCost - Overhead', 'Pure mathematical financial calculation, globally valid across all 20 currencies without physical regional dependencies.', 'verified_full'),
('boq_generator', 'Bill of Quantities (BOQ) Engine', 'costing_commercial', 'workflow_orchestration', ARRAY['src/lib/estimation/boq-engine.ts'], ARRAY['src/pages/calculator/BoqGenerator.tsx'], ARRAY['src/lib/measurement/geometry-utils.ts'], 'Generates structured bills of quantities following standard measurement division methods (NRM2, SMM7, MasterFormat, CESMM).', 'Divisions.forEach(div => div.total = sum(items.quantity * items.rate)); GrandTotal = sum(divisions.total)', 'Division numbering adapts to British NRM2 / SMM7 in Commonwealth vs CSI MasterFormat divisions in North America.', 'verified_full'),
('sequence', 'Construction Sequence & Gantt Engine', 'costing_commercial', 'workflow_orchestration', ARRAY['src/lib/engineering/sequence-engine.ts', 'src/lib/engineering/timeline-engine.ts'], ARRAY['src/pages/calculator/SequenceCalculator.tsx'], ARRAY[]::text[], 'Generates critical path method (CPM) construction schedules, concrete curing lags, predecessor dependencies, and stage gantts.', 'EarlyStart = max(Predecessors.EarlyFinish); EarlyFinish = EarlyStart + Duration; TotalFloat = LateStart - EarlyStart', 'Curing times depend on ambient climate: 7-28 days standard concrete curing.', 'verified_full'),
('regional_cost', 'Regional Cost Index Multiplier Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/regional-cost-engine.ts'], ARRAY['src/pages/calculator/RegionalCostEstimator.tsx', 'src/pages/admin/AdminRegionalCostIndices.tsx'], ARRAY['src/types/estimation.ts'], 'Location-adjusted costing: applies verified admin-configured state/province/territory cost multipliers with documented fallback warnings.', 'AdjustedCost = BaseCost * MatchedRegionalFactor; Fallback = NationalBaselineFactor', 'Supports all 20 markets with subnational jurisdiction indexing (States, Provinces, Emirates, Regions). Never guesses a multiplier.', 'verified_full'),
('cash_flow', 'Cash Flow & Milestone Disbursement Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/cash-flow-engine.ts'], ARRAY['src/pages/calculator/CashFlowCalculator.tsx', 'src/pages/admin/AdminCashFlowTemplates.tsx'], ARRAY[]::text[], 'Calculates project milestone drawdowns, contractor retention withholdings (e.g. 5%), release schedules, and monthly cash outflow curves.', 'Disbursement = MilestoneValue * (1 - RetentionRate); S-Curve Cumulative CashFlow = sum(MonthlyDisbursements)', 'Standard financial accounting logic valid globally across all currencies.', 'verified_full'),
('contractor_credit', 'Contractor Credit & Financial Health Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/contractor-credit-engine.ts'], ARRAY['src/pages/calculator/ContractorCreditCalculator.tsx', 'src/pages/admin/AdminCreditProfiles.tsx'], ARRAY[]::text[], 'Calculates contractor underwriting score, bonding capacity, debt-to-revenue ratio, working capital adequacy, and default risk rating.', 'BondingCapacity = LiquidWorkingCapital * Multiplier; DebtToRevenue = AnnualDebtService / GrossRevenue; CreditScore = weightedScore(KPIs)', 'Uses verified corporate accounting formulas; currency-agnostic with local thresholds.', 'verified_full'),
('circular_reuse', 'Circular Reuse & Waste Factor Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/circular-reuse-engine.ts'], ARRAY['src/pages/calculator/CircularReuseCalculator.tsx', 'src/pages/admin/AdminReuseFactors.tsx'], ARRAY[]::text[], 'Computes salvageable demolition material percentages, scrap avoidance value, and recycled content credits for sustainability compliance.', 'SalvageValue = sum(ItemQuantity * ReusabilityRatio * DepreciatedUnitPrice); LandfillDivertedTonnes = sum(Mass * ReusabilityRatio)', 'Material recycling rates mapped to EU waste directives, US LEED v4.1, and emerging circular economy codes.', 'verified_full'),
('embodied_carbon', 'Embodied Carbon & LCA Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/embodied-carbon-engine.ts'], ARRAY['src/pages/calculator/EmbodiedCarbonCalculator.tsx', 'src/pages/admin/AdminCarbonFactors.tsx'], ARRAY[]::text[], 'Calculates cradle-to-gate upfront embodied carbon (A1-A3) and transport carbon (A4) in kg CO2e per material line item.', 'EmbodiedCarbonKgCO2e = sum(MaterialMassKg * CarbonEmissionFactorKgCO2ePerKg); TransportCarbon = MassTonnes * DistanceKm * FreightEmissionFactor', 'Regional grid electricity emission factors and local cement clinker ratios (e.g. higher clinker substitution in EU than US).', 'verified_full'),
('estimate_refresh', 'Estimate Refresh & Price Staleness Engine', 'costing_commercial', 'workflow_orchestration', ARRAY['src/lib/estimation/estimate-refresh-engine.ts'], ARRAY['src/pages/calculator/EstimateRefreshCalculator.tsx'], ARRAY['src/lib/estimation/market-materials.ts'], 'Evaluates aged estimate line items against current verified pricebook rows, reports staleness in days, and computes price variance delta.', 'StalenessDays = (Now - EstimateDate) / (1000 * 86400); VarianceDelta = RefreshedCost - OriginalCost; PercentageChange = VarianceDelta / OriginalCost * 100', 'Preserves historical price provenance; never silently updates an approved estimate without audit logging.', 'verified_full'),
('maintenance', 'Lifecycle Maintenance & Replacement Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/maintenance-engine.ts'], ARRAY['src/pages/calculator/MaintenanceCalculator.tsx', 'src/pages/admin/AdminMaintenanceProfiles.tsx'], ARRAY[]::text[], 'Calculates 30-year lifecycle costing, preventative maintenance cycles, replacement reserves, and component service life.', 'AnnualReserve = ReplacementCost / ServiceLifeYears; NPV_Maintenance = sum(AnnualCost / (1 + DiscountRate) ^ Year)', 'Component service lifespans per ISO 15686 and ASTM E917; local discount and inflation rates.', 'verified_full'),
('price_forecast', 'Material Price Inflation Forecast Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/price-forecast-engine.ts'], ARRAY['src/pages/calculator/PriceForecastCalculator.tsx'], ARRAY[]::text[], 'Forecasts forward commodity price trends (cement, rebar, timber, copper, diesel) with upper/lower volatility confidence intervals.', 'ForecastedPrice = CurrentPrice * (1 + AnnualInflationRate) ^ (Months / 12); ConfidenceBand = ForecastedPrice * (1 +/- VolatilityZScore * StDev)', 'Incorporates national construction price indices (e.g. US PPI, UK BCIS, Eurostat, Nigeria NBS).', 'verified_full'),
('warranty_dispute', 'Warranty Coverage & Defect Dispute Engine', 'costing_commercial', 'independent_engine', ARRAY['src/lib/estimation/warranty-dispute-engine.ts'], ARRAY['src/pages/calculator/WarrantyDisputeCalculator.tsx'], ARRAY[]::text[], 'Assesses contractor defect liability periods (DLP), statutory warranty durations, latent defect claim validity, and retention release eligibility.', 'IsWithinDLP = ClaimDate <= HandoverDate + DLP_Months; EligibleRetention = RetentionAmount - sum(ApprovedDefectRemediationCosts)', 'Statutory warranty periods vary: 1-2 years DLP Commonwealth, 10 years Decennial Liability (Assurance Décennale) in FR/ME.', 'verified_full'),
('fence', 'Perimeter Fencing & External Works Engine', 'structural', 'independent_engine', ARRAY['src/lib/measurement/fence-engine.ts'], ARRAY['src/pages/calculator/FenceCalculator.tsx'], ARRAY['src/lib/measurement/geometry-utils.ts'], 'Calculates perimeter wall blocks, intermediate reinforced concrete pillars, coping stones, razor wire, and main gate openings.', 'PillarCount = ceil(NetPerimeter / PillarSpacing) + 1; BlocksPerCourse = (NetPerimeter - PillarCount * PillarWidth) / BlockLength; TotalCourses = ceil(WallHeight / BlockHeight)', 'Sandcrete/concrete masonry perimeter walls in Africa/Asia/Latin America vs timber/chain-link fencing in US/AU.', 'partially_verified'),
('roof_geometry', 'Roof Geometry & 3D Surface Engine', 'structural', 'shared_service', ARRAY['src/lib/roof/geometry-engine.ts', 'src/lib/roof/section-model.ts'], ARRAY['src/lib/roof/roof-material-engine.ts', 'src/pages/calculator/RoofingCalculator.tsx', 'src/lib/ai-foundation/engines-registry.ts'], ARRAY['src/lib/measurement/geometry-utils.ts'], 'Computes true 3D pitch-adjusted surface areas, ridge lengths, hip lengths, valley lengths, eave lengths, and rake lengths for complex roofs.', 'TrueArea = ProjectedArea / cos(PitchAngle); HipValleyFactor = sqrt(1 + tan(PitchAngle)^2 / 2); HipLength = Run * HipValleyFactor', 'Pitch expressed as degrees or rise/run slope (e.g. 4:12 to 12:12 pitch in North America). Pure mathematical geometry reusable globally.', 'verified_full'),
('roof_plan_scanner', 'Roof Plan AI Computer Vision Scanner', 'ai_measurement', 'ai_pipeline', ARRAY['src/lib/roof/plan-scanner.ts'], ARRAY['src/pages/calculator/RoofView.tsx'], ARRAY['src/lib/roof/geometry-engine.ts'], 'Vectorizes uploaded 2D architectural roof plans, detects polygon facets, ridges, hips, and dormers, and extracts dimensional geometry.', 'PolygonShoelaceArea(vertices); FacetAngleNormal = crossProduct(edge1, edge2)', 'Drawing scale calibration (metric 1:50, 1:100 vs architectural 1/4in = 1ft 0in).', 'verified_full'),
('space_measurement', 'Room & Space Geometry Engine', 'structural', 'shared_service', ARRAY['src/lib/measurement/space-engine.ts'], ARRAY['src/pages/calculator/SpaceCalculator.tsx'], ARRAY['src/lib/measurement/geometry-utils.ts'], 'Calculates gross internal area (GIA), net internal area (NIA), wall perimeter, wall heights, ceiling surface, and volume for multi-room floorplans.', 'GIA = sum(RoomNetArea + WallFootprintArea); WallSurface = RoomPerimeter * RoomHeight - sum(OpeningsArea)', 'Standard measurement codes (RICS in UK/Commonwealth, BOMA / ANSI Z765 in US/CA).', 'verified_full'),
('measurement_confidence', 'Measurement Confidence & Anomaly Engine', 'ai_measurement', 'shared_service', ARRAY['src/lib/measurement/confidence-engine.ts'], ARRAY['src/lib/ai-foundation/orchestrator.ts'], ARRAY[]::text[], 'Scores confidence (0-100%) of extracted building dimensions, flags geometric contradictions (e.g. wall height < 2m), and warns of missing inputs.', 'ConfidenceScore = BaseConfidence * PenaltyMissingDeductions * CalibrationVerificationFactor', 'Deterministic validation rules, independent of country.', 'verified_full'),
('measurement_explanation', 'Measurement Transparency & Explanation Engine', 'ai_measurement', 'shared_service', ARRAY['src/lib/measurement/explanation-engine.ts'], ARRAY['src/lib/ai-foundation/orchestrator.ts'], ARRAY[]::text[], 'Produces human-readable, step-by-step mathematical proof of every quantity takeoff line item, citing formula, waste factor, and unit conversions.', 'generateSteps(formulaName, inputs, intermediateValues, roundingRule, finalValue)', 'Multi-language explanations preserving canonical underlying numbers.', 'verified_full'),
('quotation_generator', 'Quotation & Commercial Proposal Engine', 'costing_commercial', 'workflow_orchestration', ARRAY['src/lib/measurement/quotation-engine.ts'], ARRAY['src/pages/calculator/QuotationGenerator.tsx'], ARRAY['src/lib/estimation/quote-export.ts'], 'Compiles multi-trade estimates into client-ready formal bids and quotations with terms, validity dates, payment schedules, and PDF branding.', 'Subtotal = sum(LineTotals); TaxAmount = Subtotal * TaxRate; GrandTotal = Subtotal + TaxAmount', 'Respects local sales tax / VAT / GST rules (e.g. 7.5% VAT in NG; 20% VAT in GB; State Sales Tax in US; 10% GST in AU; 18% GST in IN).', 'verified_full'),
('offline_field', 'Offline Field Sync & Takeoff Engine', 'costing_commercial', 'workflow_orchestration', ARRAY['src/lib/estimation/offline-field-engine.ts'], ARRAY['src/pages/admin/AdminFieldSync.tsx'], ARRAY[]::text[], 'Manages offline site inspection queues, SQLite/IndexedDB caching, timestamp conflict resolution, and deterministic cloud database sync.', 'resolveSyncConflict(localTimestamp, serverTimestamp, mutationVector)', 'Designed for low-connectivity construction job sites worldwide.', 'verified_full'),
('ai_image_estimator', 'AI Photo & Plan Feature Extractor', 'ai_measurement', 'ai_pipeline', ARRAY['src/pages/calculator/ImageEstimation.tsx', 'src/lib/ai-foundation/copilot-client.ts'], ARRAY['src/pages/calculator/ImageEstimation.tsx'], ARRAY['src/lib/ai-foundation/orchestrator.ts'], 'Multi-modal vision extraction: reads site photos or architectural drawings, extracts elements, and routes to deterministic calculators.', 'VisionModel.extract(image) -> Dimensions -> executeEngine(deterministicId, validatedInputs)', 'AI vision never invents formulas or prices; always delegates to registered deterministic engines.', 'verified_full'),
('ai_color_assistant', 'AI Paint Color & Palette Advisor', 'ai_measurement', 'ai_pipeline', ARRAY['src/lib/ai-foundation/orchestrator.ts'], ARRAY['src/pages/calculator/PaintingCalculator.tsx'], ARRAY['src/lib/estimation/paint-engine.ts'], 'Maps user aesthetic requests or room lighting conditions to verified regional paint manufacturer color palettes.', 'ColorHarmonyMatching(CIELAB_Coordinates, LightReflectanceValue)', 'Dulux, Asian Paints, Sherwin-Williams, Benjamin Moore, Berger, Coral, Nippon Paint local palettes.', 'verified_full'),
('conversational_estimator', 'Multi-Lingual Conversational Estimator', 'ai_measurement', 'ai_pipeline', ARRAY['src/lib/estimation/conversational-engine.ts', 'src/lib/ai-foundation/copilot-client.ts'], ARRAY['src/pages/calculator/ConversationalEstimator.tsx'], ARRAY['src/lib/ai-foundation/orchestrator.ts'], 'Natural language understanding for trade takeoffs across 10+ languages (English, French, Spanish, German, Portuguese, Swahili, Arabic, etc.).', 'NLP.parseIntentAndEntities(text) -> canonicalValues -> executeEngine(taskEngine, normalizedUnits)', 'Translates colloquial regional trade terms (e.g. ''caterpillar/dumper'', ''parpaing'', ''bata merah'', ''chuveiro'', ''sandcrete'') to canonical materials.', 'verified_full'),
('count_vision', 'Drawing Symbol & Fixture Count Vision Engine', 'ai_measurement', 'ai_pipeline', ARRAY['src/lib/estimation/count-vision-engine.ts'], ARRAY['src/pages/calculator/CountVisionCalculator.tsx', 'src/pages/admin/AdminCountVision.tsx'], ARRAY[]::text[], 'Automated object detection on blueprint PDFs and architectural plans for electrical outlets, light fixtures, plumbing points, and doors.', 'BoundingBoxMatch(symbolTemplate, drawingCanvas, iouThreshold) -> detectedCount', 'Standard architectural drafting symbols (ANSI/IEEE in US vs IEC in Europe/Commonwealth).', 'verified_full'),
('defect_diagnosis', 'Visual Defect & Crack Diagnosis Engine', 'ai_measurement', 'ai_pipeline', ARRAY['src/lib/estimation/defect-diagnosis-engine.ts'], ARRAY['src/pages/calculator/DefectDiagnosisCalculator.tsx', 'src/pages/admin/AdminDefects.tsx'], ARRAY[]::text[], 'Classifies plaster cracks, structural shear fissures, concrete spalling, rising damp, and efflorescence from site photos.', 'ClassifyCrackPattern(widthMm, orientation, propagationRate) -> RootCauseSeverityRating', 'Building pathology rules for structural movement vs shrinkage cracks.', 'verified_full'),
('surface_assessment', 'Surface Condition & Substrate Prep Engine', 'ai_measurement', 'ai_pipeline', ARRAY['src/lib/wallfinishing/quantity-engine.ts'], ARRAY['src/pages/calculator/WallFinishingEstimator.tsx', 'src/pages/admin/AdminSurfaceConditions.tsx'], ARRAY['src/lib/wallfinishing/materials.ts'], 'Evaluates substrate porosity, moisture levels, flaking paint percentage, and assigns prep multiplier factors (sanding, washing, bonding primer).', 'PrepMultiplier = 1.0 + (PorosityLevel * 0.15) + (DamageSeverity * 0.20)', 'Verified substrate types across blockwork, drywall, concrete, and lime plaster.', 'verified_full'),
('learning_engine', 'Continuous Estimation Learning & Promotion Engine', 'intelligence', 'intelligence_crawler', ARRAY['src/lib/learning/learning-engine.ts'], ARRAY['src/pages/admin/AdminAiLearningAssistant.tsx', 'src/pages/admin/AdminLearningReview.tsx'], ARRAY[]::text[], 'Tracks user edits and contractor bid adjustments against baseline estimates, continuously refining waste percentages and crew outputs.', 'BayesianUpdate(priorParam, observedContractorAdjustments, sampleConfidenceWeight)', 'Per-market learning partitions; adjustments in Nigeria do not alter US drywall production baselines.', 'verified_full'),
('price_validator', 'Market Price Statistical Validator Engine', 'intelligence', 'intelligence_crawler', ARRAY['src/lib/market-intelligence/price-validator.ts'], ARRAY['src/pages/admin/AdminPricePipeline.tsx', 'src/pages/admin/AdminPriceSubmissions.tsx'], ARRAY[]::text[], 'Statistical anomaly filtering for crowdsourced and supplier price updates: computes interquartile ranges (IQR), z-scores, and rejects outliers.', 'IQR = Q3 - Q1; IsValid = (Price >= Q1 - 1.5 * IQR) and (Price <= Q3 + 1.5 * IQR)', 'Independent statistical bounds computed per market and currency code.', 'verified_full'),
('market_crawler', 'Retail & Wholesaler Price Crawl Engine', 'intelligence', 'intelligence_crawler', ARRAY['src/lib/market-intelligence/crawler/crawl-engine.ts'], ARRAY['src/pages/admin/AdminPriceScan.tsx'], ARRAY['src/lib/market-intelligence/price-validator.ts'], 'Extracts catalog product pricing, package volume specs, and supplier stock availability from construction merchants.', 'ParseProductSpec(rawHtml) -> { unitPrice, packSize, materialRole, effectiveDate }', 'Strictly gates unverified scraped candidate prices from production estimates until approved by admin.', 'verified_full')
